const JSON_HEADERS = { "content-type": "application/json; charset=utf-8" };

function json(data, status) {
  return new Response(JSON.stringify(data), { status: status || 200, headers: JSON_HEADERS });
}

async function loadActors(store) {
  const { blobs } = await store.list();
  if (blobs.length === 0) {
    await Promise.all(SEED.map((a) => store.setJSON(a.id, a)));
    return SEED.slice();
  }
  const actors = await Promise.all(blobs.map((b) => store.get(b.key, { type: "json" })));
  return actors.filter(Boolean);
}

function slug(s) {
  return String(s)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    .slice(0, 80);
}

const REQUIRED_FIELDS = ["nombre", "categoria"];
const VALID_CATEGORIAS = ["competidores", "mercados", "aliados", "autoridades"];

export default async (req) => {
  const store = getStore({ name: "radar360", consistency: "strong" });

  if (req.method === "GET") {
    const actors = await loadActors(store);
    return json(actors);
  }

  if (req.method === "POST") {
    let body;
    try {
      body = await req.json();
    } catch (e) {
      return json({ error: "invalid_json" }, 400);
    }
    for (const f of REQUIRED_FIELDS) {
      if (!body[f] || typeof body[f] !== "string" || !body[f].trim()) {
        return json({ error: "missing_field", field: f }, 400);
      }
    }
    if (!VALID_CATEGORIAS.includes(body.categoria)) {
      return json({ error: "invalid_categoria" }, 400);
    }
    const { blobs } = await store.list();
    if (blobs.length >= 2000) {
      return json({ error: "too_many_actors" }, 429);
    }
    const now = new Date().toISOString();
    const newActor = {
      id: body.categoria + "-" + slug(body.nombre) + "-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 6),
      nombre: body.nombre.trim(),
      categoria: body.categoria,
      sector: (body.sector || "").trim(),
      confianza: body.confianza || "por_identificar",
      justificacion: (body.justificacion || "").trim(),
      estado: body.estado || "por_validar",
      mostrarEnRadar: body.mostrarEnRadar !== false,
      origenTaller: true,
      createdAt: now,
      updatedAt: now,
    };
    // each actor is its own blob key, so concurrent adds from different
    // participants never collide on a shared read-modify-write cycle
    await store.setJSON(newActor.id, newActor);
    return json(newActor, 201);
  }

  if (req.method === "PATCH") {
    let body;
    try {
      body = await req.json();
    } catch (e) {
      return json({ error: "invalid_json" }, 400);
    }
    if (!body.id || typeof body.id !== "string") {
      return json({ error: "missing_id" }, 400);
    }
    const existing = await store.get(body.id, { type: "json" });
    if (!existing) {
      return json({ error: "not_found" }, 404);
    }
    const patch = Object.assign({}, body.patch || {});
    delete patch.id;
    delete patch.createdAt;
    const updated = Object.assign({}, existing, patch, { updatedAt: new Date().toISOString() });
    await store.setJSON(body.id, updated);
    return json(updated);
  }


  return json({ error: "method_not_allowed" }, 405);
};
